  .hero-bankrot-sroki__pill span {
    padding: 0.55rem 1rem;
    background: rgba(255, 255, 255, 0.94);
    border: 1px solid #e2e8f0;
    border-radius: 999px;
    font-size: 0.8125rem;
    font-weight: 600;
    color: #475569;
    box-shadow: 0 2px 10px rgba(15, 23, 42, 0.05);
    white-space: nowrap;
  }


